def affine(p):
    (u, v) = (p['u'], p['v'])
    f = np.c_[np.ones(len(u)), u]
    keep = np.ones(len(u), bool)
    for _ in range(8):
        w = np.linalg.lstsq(f[keep], v[keep], rcond=None)[0]
        r = np.linalg.norm(v - f @ w, axis=1)
        keep = r < max(0.001, 4 * np.median(r))
    return (w, r)

def poly(u, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(u))] + [np.prod(u[:, p], axis=1) for k in range(1, d + 1) for p in combinations_with_replacement(range(4), k)])

def anova(a):
    ds = (a[:, None, :] - a[None, :, :]) ** 2
    k = np.exp(-ds / 2)
    terms = [k[:, :, i] for i in range(4)]
    pairs = [terms[i] * terms[j] for i in range(4) for j in range(i)]
    return np.stack([*terms, *pairs])

def extras(u):
    from itertools import combinations
    cols = []
    labels = []

    def add(label, col):
        labels.append(label)
        cols.append(col)
    for j in range(4):
        v = u[:, j]
        for k in (0.7, 1.2, 1.7, 2.3):
            for fn in (np.sin, np.cos, np.tanh):
                add((fn.__name__, j, k), fn(k * v))
        for h in range(4):
            w = u[:, h]
            add(('rational', j, h), v / (1 + w * w))
            add(('tanhProduct', j, h), v * np.tanh(w))
            add(('sinProduct', j, h), v * np.sin(w))
            add(('denomProduct', j, h), v * w / (1 + w * w))
    for (j, h) in combinations(range(4), 2):
        for sign in (-1, 1):
            for k in (0.75, 1.25, 1.7):
                for fn in (np.sin, np.cos, np.tanh):
                    add((fn.__name__, j, h, sign, k), fn(k * (u[:, j] + sign * u[:, h])))
    return (np.column_stack(cols), labels)

def ridge(U, Y, ix, fn, d, depth=1, starts=14):
    from scipy.optimize import least_squares
    from scipy.linalg import qr
    from scipy.linalg import solve_triangular
    P = poly(U, d)
    ps = P[ix]
    (Q, R) = qr(ps, mode='economic')
    V = Y[ix]
    RY = V - Q @ (Q.T @ V)
    if fn == 'sin':
        transform = lambda u: np.column_stack([np.sin(u), np.cos(u)])
    if fn == 'tanh':
        transform = np.tanh
    if fn == 'rat':
        transform = lambda u: u / (1 + u * u)
    if fn == 'soft':
        transform = lambda u: u / np.sqrt(1 + u * u)
    dim = 4 if fn == 'sin' else 5

    def enrich(T, p):
        return transform(T @ p[:4] + (p[4] if dim == 5 else 0)).reshape(len(T), -1)

    def res(p, ret=False):
        F = np.column_stack([enrich(U, pp) for pp in p.reshape(-1, dim)])
        QF = Q.T @ F[ix]
        M = F[ix] - Q @ QF
        w = np.linalg.lstsq(M, RY, rcond=None)[0]
        if ret:
            return P @ solve_triangular(R, Q.T @ V - QF @ w) + F @ w
        return (M @ w - RY).ravel()
    local = np.random.default_rng(817)
    axes = np.r_[np.eye(4), local.normal(size=(starts, 4)) * 0.85]
    init = [np.r_[a0, 0] if dim == 5 else a0 for a0 in axes]
    bds = ([-3] * dim, [3] * dim)
    p = []
    for k in range(depth):
        opts = [least_squares(res, np.r_[p, p0], bounds=(bds[0] * (k + 1), bds[1] * (k + 1)), max_nfev=65, ftol=3e-07) for p0 in init if np.max(abs(p0)) < 3]
        best = min(opts, key=lambda o: o.cost)
        p = best.x
    return (res(p, True), p, np.mean(abs(best.fun)))
